CREATE TABLE public.profiles (id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE, display_name text, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.profiles TO anon;
GRANT SELECT, INSERT, UPDATE ON public.profiles TO authenticated;
GRANT ALL ON public.profiles TO service_role;
ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Profiles viewable by all" ON public.profiles FOR SELECT USING (true);
CREATE POLICY "Users update own profile" ON public.profiles FOR UPDATE TO authenticated USING (auth.uid() = id);
CREATE POLICY "Users insert own profile" ON public.profiles FOR INSERT TO authenticated WITH CHECK (auth.uid() = id);
CREATE OR REPLACE FUNCTION public.handle_new_user() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ BEGIN INSERT INTO public.profiles (id, display_name) VALUES (NEW.id, COALESCE(NEW.raw_user_meta_data->>'full_name', NEW.raw_user_meta_data->>'name', split_part(NEW.email, '@', 1))); RETURN NEW; END; $$;
CREATE TRIGGER on_auth_user_created AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION public.handle_new_user();
CREATE TABLE public.questions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE, title text NOT NULL DEFAULT '', option_a_label text NOT NULL DEFAULT 'Option A', option_a_image text NOT NULL, option_b_label text NOT NULL DEFAULT 'Option B', option_b_image text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), category text NOT NULL DEFAULT 'Other', occasion text, budget text, visibility text NOT NULL DEFAULT 'public', duration_hours integer NOT NULL DEFAULT 24, ends_at timestamptz, decided_choice text, decided_at timestamptz, CONSTRAINT questions_category_check CHECK (category IN ('Tech','Fashion','Shoes','Bags','Beauty','Home & Living','Sports & Outdoor','Kitchen','Gaming','Books & Hobbies','Other')), CONSTRAINT questions_visibility_check CHECK (visibility IN ('public','link')), CONSTRAINT questions_duration_check CHECK (duration_hours IN (1,24,72)), CONSTRAINT questions_decided_choice_check CHECK (decided_choice IS NULL OR decided_choice IN ('a','b','neither')));
GRANT SELECT ON public.questions TO anon;
GRANT SELECT, INSERT, UPDATE, DELETE ON public.questions TO authenticated;
GRANT ALL ON public.questions TO service_role;
ALTER TABLE public.questions ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Questions viewable by all" ON public.questions FOR SELECT USING (true);
CREATE POLICY "Users create own questions" ON public.questions FOR INSERT TO authenticated WITH CHECK (auth.uid() = user_id);
CREATE POLICY "Users delete own questions" ON public.questions FOR DELETE TO authenticated USING (auth.uid() = user_id);
CREATE INDEX questions_category_idx ON public.questions(category);
CREATE INDEX questions_feed_idx ON public.questions(visibility, ends_at, created_at DESC);
ALTER TABLE public.profiles ADD COLUMN interests text[] NOT NULL DEFAULT ARRAY['Tech','Fashion','Shoes','Bags','Beauty','Home & Living','Sports & Outdoor','Kitchen','Gaming','Books & Hobbies','Other'];
ALTER TABLE public.profiles ADD COLUMN onboarded boolean NOT NULL DEFAULT false;
ALTER TABLE public.profiles ADD CONSTRAINT profiles_interests_nonempty CHECK (cardinality(interests) >= 1);
CREATE TABLE public.votes (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), question_id uuid NOT NULL REFERENCES public.questions(id) ON DELETE CASCADE, user_id uuid NOT NULL, choice text NOT NULL CHECK (choice IN ('a','b')), created_at timestamptz NOT NULL DEFAULT now(), anonymous boolean NOT NULL DEFAULT false, UNIQUE(question_id,user_id));
GRANT SELECT, INSERT ON public.votes TO anon;
GRANT SELECT, INSERT, UPDATE, DELETE ON public.votes TO authenticated;
GRANT ALL ON public.votes TO service_role;
ALTER TABLE public.votes ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Votes viewable by all" ON public.votes FOR SELECT USING (true);
CREATE POLICY "Users cast own vote" ON public.votes FOR INSERT TO authenticated WITH CHECK (auth.uid() = user_id);
CREATE POLICY "Users remove own vote" ON public.votes FOR DELETE TO authenticated USING (auth.uid() = user_id);
CREATE POLICY "Guests cast anonymous vote" ON public.votes FOR INSERT TO anon WITH CHECK (anonymous = true);
CREATE INDEX votes_user_idx ON public.votes(user_id);
CREATE POLICY "Public read question images" ON storage.objects FOR SELECT USING (bucket_id = 'question-images');
CREATE POLICY "Users delete own question images" ON storage.objects FOR DELETE TO authenticated USING (bucket_id = 'question-images' AND (storage.foldername(name))[1] = auth.uid()::text);
CREATE OR REPLACE FUNCTION public.set_question_ends_at() RETURNS trigger LANGUAGE plpgsql SET search_path = public AS $$ BEGIN NEW.ends_at := COALESCE(NEW.created_at, now()) + make_interval(hours => NEW.duration_hours); RETURN NEW; END; $$;
CREATE TRIGGER questions_set_ends_at BEFORE INSERT ON public.questions FOR EACH ROW EXECUTE FUNCTION public.set_question_ends_at();
CREATE OR REPLACE FUNCTION public.ensure_voting_open() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ BEGIN IF EXISTS (SELECT 1 FROM public.questions WHERE id = NEW.question_id AND ends_at IS NOT NULL AND ends_at < now()) THEN RAISE EXCEPTION 'Voting has ended for this question'; END IF; RETURN NEW; END; $$;
CREATE TRIGGER votes_ensure_open BEFORE INSERT OR UPDATE ON public.votes FOR EACH ROW EXECUTE FUNCTION public.ensure_voting_open();
CREATE TABLE public.vote_feedback (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), question_id uuid NOT NULL REFERENCES public.questions(id) ON DELETE CASCADE, voter_id uuid NOT NULL, anonymous boolean NOT NULL DEFAULT false, tags text[] NOT NULL DEFAULT '{}', comment text, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(question_id,voter_id), CONSTRAINT vote_feedback_comment_len CHECK (comment IS NULL OR char_length(comment) <= 140), CONSTRAINT vote_feedback_tags_valid CHECK (tags <@ ARRAY['Design','Quality','Price','Style','Features']::text[]));
GRANT SELECT, INSERT ON public.vote_feedback TO anon, authenticated;
GRANT ALL ON public.vote_feedback TO service_role;
ALTER TABLE public.vote_feedback ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Feedback viewable by all" ON public.vote_feedback FOR SELECT USING (true);
CREATE POLICY "Members add own feedback" ON public.vote_feedback FOR INSERT TO authenticated WITH CHECK (auth.uid() = voter_id AND anonymous = false AND EXISTS (SELECT 1 FROM public.votes v WHERE v.question_id = vote_feedback.question_id AND v.user_id = vote_feedback.voter_id));
CREATE POLICY "Guests add anonymous feedback" ON public.vote_feedback FOR INSERT TO anon WITH CHECK (anonymous = true AND EXISTS (SELECT 1 FROM public.votes v WHERE v.question_id = vote_feedback.question_id AND v.user_id = vote_feedback.voter_id AND v.anonymous = true));
CREATE OR REPLACE FUNCTION public.feed_page(p_voter uuid,p_interests text[],p_category text,p_sort text,p_limit int,p_offset int) RETURNS TABLE(id uuid,matched boolean) LANGUAGE sql STABLE SECURITY INVOKER SET search_path = public AS $$ SELECT q.id,(p_interests IS NULL OR q.category = ANY(p_interests)) AS matched FROM public.questions q WHERE q.visibility='public' AND (q.ends_at IS NULL OR q.ends_at>now()) AND (p_category IS NULL OR q.category=p_category) AND (auth.uid() IS NULL OR q.user_id<>auth.uid()) AND (p_voter IS NULL OR NOT EXISTS(SELECT 1 FROM public.votes v WHERE v.question_id=q.id AND v.user_id=p_voter)) ORDER BY (p_interests IS NULL OR q.category=ANY(p_interests)) DESC,CASE WHEN p_sort='ending' THEN q.ends_at END ASC NULLS LAST,q.created_at DESC,q.id LIMIT LEAST(GREATEST(p_limit,1),50) OFFSET GREATEST(p_offset,0) $$;
GRANT EXECUTE ON FUNCTION public.feed_page(uuid,text[],text,text,int,int) TO anon,authenticated;
CREATE OR REPLACE FUNCTION public.decide_question(p_question uuid,p_choice text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF p_choice NOT IN ('a','b','neither') THEN RAISE EXCEPTION 'Invalid choice'; END IF; UPDATE public.questions SET decided_choice=p_choice,decided_at=now(),ends_at=LEAST(COALESCE(ends_at,now()),now()) WHERE id=p_question AND user_id=auth.uid(); IF NOT FOUND THEN RAISE EXCEPTION 'Question not found'; END IF; END; $$;
REVOKE EXECUTE ON FUNCTION public.decide_question(uuid,text) FROM public,anon;
GRANT EXECUTE ON FUNCTION public.decide_question(uuid,text) TO authenticated;
CREATE TABLE public.notifications (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL,question_id uuid NOT NULL REFERENCES public.questions(id) ON DELETE CASCADE,kind text NOT NULL CHECK(kind IN ('votes','ended')),count integer NOT NULL DEFAULT 1,read boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,UPDATE ON public.notifications TO authenticated;
GRANT ALL ON public.notifications TO service_role;
ALTER TABLE public.notifications ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Users read own notifications" ON public.notifications FOR SELECT TO authenticated USING(auth.uid()=user_id);
CREATE POLICY "Users mark own notifications" ON public.notifications FOR UPDATE TO authenticated USING(auth.uid()=user_id) WITH CHECK(auth.uid()=user_id);
CREATE UNIQUE INDEX notifications_unread_votes_uniq ON public.notifications(question_id) WHERE kind='votes' AND read=false;
CREATE UNIQUE INDEX notifications_ended_uniq ON public.notifications(question_id) WHERE kind='ended';
CREATE INDEX notifications_user_idx ON public.notifications(user_id,updated_at DESC);
CREATE OR REPLACE FUNCTION public.notify_new_vote() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE owner uuid; BEGIN SELECT user_id INTO owner FROM public.questions WHERE id=NEW.question_id; IF owner IS NULL OR owner=NEW.user_id THEN RETURN NEW; END IF; INSERT INTO public.notifications(user_id,question_id,kind) VALUES(owner,NEW.question_id,'votes') ON CONFLICT(question_id) WHERE kind='votes' AND read=false DO UPDATE SET count=public.notifications.count+1,updated_at=now(); RETURN NEW; END; $$;
CREATE TRIGGER votes_notify AFTER INSERT ON public.votes FOR EACH ROW EXECUTE FUNCTION public.notify_new_vote();
CREATE OR REPLACE FUNCTION public.sync_ended_notifications() RETURNS void LANGUAGE sql SECURITY DEFINER SET search_path=public AS $$ INSERT INTO public.notifications(user_id,question_id,kind,created_at,updated_at) SELECT q.user_id,q.id,'ended',q.ends_at,q.ends_at FROM public.questions q WHERE q.user_id=auth.uid() AND q.ends_at<=now() AND q.decided_at IS NULL ON CONFLICT(question_id) WHERE kind='ended' DO NOTHING; $$;
REVOKE EXECUTE ON FUNCTION public.sync_ended_notifications() FROM public,anon;
GRANT EXECUTE ON FUNCTION public.sync_ended_notifications() TO authenticated;